<?php
namespace App\Services; use App\Core\Database;use App\Core\Auth;
final class TaskService{public function create(array $d):int{$title=trim((string)$d['title']);if($title==='')throw new \InvalidArgumentException('Task title is required');$s=Database::pdo()->prepare('INSERT INTO tasks(tenant_id,client_id,business_id,project_id,workflow_step_instance_id,assigned_user_id,title,description,status,priority,due_at,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$d['client_id']?:null,$d['business_id']?:null,$d['project_id']?:null,$d['workflow_step_instance_id']?:null,$d['assigned_user_id']?:Auth::id(),$title,$d['description']??null,$d['status']??'open',$d['priority']??'normal',$d['due_at']?:null]);$id=(int)Database::pdo()->lastInsertId();(new ActivityService)->record('TASK_CREATED','Tasks','task',$id);return $id;}public function complete(int $id):void{Database::pdo()->prepare('UPDATE tasks SET status="completed",completed_at=NOW(),updated_at=NOW() WHERE id=?')->execute([$id]);(new ActivityService)->record('TASK_COMPLETED','Tasks','task',$id);}}
